"""Generates `r4a_orbit_stabiliser_count` questions (easy, medium, hard) and the exam chain
`exd_x_r4a_orbit_stabiliser_count`.

``uc2-orbit-stabiliser-count`` (``abstract-algebra``, answer ``number``): sizes of orbits and stabilisers, using
|G| = |orbit| × |stabiliser|.

* easy: the cyclic group G = ⟨σ⟩ generated by a product of disjoint cycles acts on {1, ..., n}; find the order of the
  stabiliser of a point (the order of G divided by the length of that point's cycle).
* medium: the dihedral group D_n of order 2n acts on the colourings of the vertices of a regular n-gon in which k vertices
  are black; find the size of the orbit of a colouring.
* hard: D_n acts on colourings of the n vertices with three colours, built from a repeating block so that some symmetries
  fix the colouring; find the size of its orbit.
* exam: D_n acts on black-and-white colourings: (a) the order of the stabiliser of a colouring, (b) the size of its orbit
  (follows through from (a)), (c) how many elements of D_n send the colouring to a given colouring in its orbit (follows
  through from (a)), (d) the stabiliser order of a second colouring whose orbit size is given.

The group elements are listed in full (n rotations x → x + j and n reflections x → j - x on the vertices 0, ..., n - 1),
and the stabiliser and orbit are found by acting with every element; the key is checked against |G| = |orbit||stabiliser|.
"""

from __future__ import annotations

from math import lcm

from ..core import attempts, check, generator, phrase
from ._r4a_alg_kit import cycles, from_cycles, number_part, number_question, product_text, with_latex


def _d_maps(n):
    """The 2n symmetries of the n-gon on vertices 0..n-1, as tuples of images."""
    rotations = [tuple((x + j) % n for x in range(n)) for j in range(n)]
    reflections = [tuple((j - x) % n for x in range(n)) for j in range(n)]
    return rotations, reflections


def _act(g, colouring):
    """The colouring (tuple of colours by vertex) after moving each vertex v to g[v]."""
    out = [None] * len(colouring)
    for v, c in enumerate(colouring):
        out[g[v]] = c
    return tuple(out)


def _stab_and_orbit(n, colouring):
    rotations, reflections = _d_maps(n)
    elements = rotations + reflections
    images = [_act(g, colouring) for g in elements]
    stab = sum(1 for im in images if im == colouring)
    orbit = set(images)
    return stab, len(orbit), elements, images


def _symmetric_black(rng, n):
    """A set of black vertices built from a repeating block, sometimes mirror-symmetric, so some symmetries fix it."""
    p = rng.choice([d for d in range(2, n) if n % d == 0] or [n])
    base = set(rng.sample(range(p), rng.randint(1, p - 1)))
    if rng.random() < 0.5:
        base |= {(-x) % p for x in base}
    return {v for v in range(n) if v % p in base}


def _black_text(colouring):
    return "{" + ", ".join(str(v) for v, c in enumerate(colouring) if c == "B") + "}"


# -- easy ------------------------------------------------------------------------------------------------------

_EASY_STEMS = (
    "Let σ = {sigma} in S_{n} and let G = ⟨σ⟩ act on {{1, ..., {n}}}. Find the order of the stabiliser of {x} in G.",
    "The cyclic group G generated by σ = {sigma} acts on {{1, ..., {n}}}. How many elements of G fix the point {x}?",
)


def _easy(rng):
    for _ in attempts(3000, "disjoint cycles with a point whose stabiliser is non-trivial and not the orbit size"):
        n = rng.choice([9, 10, 11, 12])
        lens = [rng.randint(2, 7) for _ in range(rng.randint(2, 3))]
        if sum(lens) > n or len(set(lens)) < 2:
            continue
        order = lcm(*lens)
        pts = rng.sample(range(1, n + 1), sum(lens))
        cyc, at = [], 0
        for length in lens:
            cyc.append(tuple(pts[at : at + length]))
            at += length
        short = min(range(len(lens)), key=lambda i: lens[i])
        x = cyc[short][rng.randrange(lens[short])]
        stab = order // lens[short]
        if stab > 1 and stab != lens[short] and order <= 60 and stab != order:
            break
    sigma = from_cycles(cyc, n)
    # act by every power of sigma and count the powers that fix x
    fixing = 0
    power_map = tuple(range(1, n + 1))
    for _ in range(order):
        fixing += power_map[x - 1] == x
        power_map = tuple(sigma[power_map[i] - 1] for i in range(n))
    check(fixing == stab, "counting the powers that fix x differs from |G| / |orbit|")
    check(sorted(map(len, cycles(sigma))) == sorted(lens), "cycle type differs from the draw")
    slips = [
        (lens[short], "stabiliser-order-as-orbit-size"),
        (order, "stabiliser-order-as-group-order"),
        (1, "stabiliser-order-trivial-assumed"),
        (order - lens[short], "stabiliser-order-subtracts-orbit"),
        (sum(lens), None),
    ]
    return number_question(
        phrase(rng, _EASY_STEMS, sigma=product_text(cyc), n=n, x=x),
        stab,
        [
            f"σ has order lcm({', '.join(map(str, lens))}) = {order}, so |G| = {order}.",
            f"The orbit of {x} is its cycle, of length {lens[short]}, so |Stab({x})| = {order}/{lens[short]} = {stab}.",
        ],
        slips,
        lo=1,
    )


# -- medium ----------------------------------------------------------------------------------------------------

_MED_STEMS = (
    "The vertices of a regular {n}-gon are labelled 0, 1, ..., {m} in order. The dihedral group D_{n} of order {g} (rotations "
    "and reflections of the {n}-gon) acts on colourings of the vertices. In a colouring c the vertices {black} are black and "
    "the others white. How many different colourings can be reached from c by elements of D_{n}?",
    "A regular {n}-gon has vertices 0, 1, ..., {m} in order. Its symmetry group D_{n}, of order {g}, acts on black-and-white "
    "colourings of the vertices. Take the colouring with exactly the vertices {black} black. Find the size of its orbit "
    "under D_{n}.",
)


def _colouring(n, black):
    return tuple("B" if v in black else "W" for v in range(n))


def _medium(rng):
    for _ in attempts(3000, "a colouring with a non-trivial stabiliser"):
        n = rng.randint(6, 16)
        black = (
            _symmetric_black(rng, n) if rng.random() < 0.6 else set(rng.sample(range(n), rng.randint(3, min(6, n - 2))))
        )
        c = _colouring(n, black)
        stab, orbit, elements, images = _stab_and_orbit(n, c)
        if stab >= 2 and orbit != n and 3 <= len(black) <= n - 2:
            break
    check(stab * orbit == 2 * n, "|stabiliser| × |orbit| differs from |D_n|")
    rot_stab = sum(1 for g, im in zip(elements[:n], images[:n]) if im == c)
    slips = [
        (stab, "orbit-size-as-stabiliser-order"),
        (2 * n, "orbit-size-whole-group"),
        (n // rot_stab if n % rot_stab == 0 else None, "orbit-size-rotations-only"),
        (n, "orbit-size-uses-n-not-2n"),
        (orbit + stab, None),
    ]
    return number_question(
        phrase(rng, _MED_STEMS, n=n, m=n - 1, g=2 * n, black=_black_text(c)),
        orbit,
        [
            f"Acting with all {2 * n} elements, exactly {stab} of them leave the colouring unchanged.",
            f"|orbit| = |D_{n}|/|stabiliser| = {2 * n}/{stab} = {orbit}.",
        ],
        slips,
        lo=1,
    )


# -- hard ------------------------------------------------------------------------------------------------------

_HARD_STEMS = (
    "The {n} vertices of a regular {n}-gon, numbered 0, 1, ..., {m} in order, are coloured red (R), green (G) or blue (B) "
    "as {word} reads from vertex 0 round to vertex {m}. The dihedral group D_{n} of order {g} acts by rotating and "
    "reflecting the {n}-gon. How many different colourings can this one be turned into?",
    "A regular {n}-gon has its vertices 0, ..., {m} coloured {word} (R red, G green, B blue) in order. D_{n}, of order {g}, "
    "acts on such colourings by rotations and reflections. Find the number of colourings in the orbit of this one.",
)


def _hard_word(rng, n):
    for _ in attempts(500, "a repeating block"):
        p = rng.choice([d for d in range(2, n) if n % d == 0 and d >= 3])
        block = [rng.choice("RGB") for _ in range(p)]
        if len(set(block)) < 2:
            continue
        if rng.random() < 0.5:
            # a mirror-symmetric block: u followed by the reverse of its interior
            half = block[: (p + 1) // 2]
            block = half + (half[::-1] if p % 2 == 0 else half[:-1][::-1])
        return tuple(block * (n // p))
    raise AssertionError  # pragma: no cover


def _hard(rng):
    for _ in attempts(500, "a three-colour word with a non-trivial stabiliser and a reflection or rotation story"):
        n = rng.choice([6, 8, 9, 10, 12, 14, 15, 16, 18])
        c = _hard_word(rng, n)
        stab, orbit, elements, images = _stab_and_orbit(n, c)
        rot_stab = sum(1 for im in images[:n] if im == c)
        if stab >= 2 and orbit not in (n, 2 * n) and len(set(c)) >= 2 and stab != rot_stab:
            break
    check(stab * orbit == 2 * n, "|stabiliser| × |orbit| differs from |D_n|")
    slips = [
        (stab, "orbit-size-as-stabiliser-order"),
        (n // rot_stab, "orbit-size-rotations-only"),
        (2 * n, "orbit-size-whole-group"),
        (2 * n // rot_stab if (2 * n) % rot_stab == 0 else None, "orbit-size-ignores-reflections-in-stabiliser"),
        (n, "orbit-size-uses-n-not-2n"),
    ]
    return number_question(
        phrase(rng, _HARD_STEMS, n=n, m=n - 1, g=2 * n, word="".join(c)),
        orbit,
        [
            f"{rot_stab} rotation{'s' if rot_stab != 1 else ''} and {stab - rot_stab} reflection{'s' if stab - rot_stab != 1 else ''} fix the colouring, so |stabiliser| = {stab}.",
            f"|orbit| = {2 * n}/{stab} = {orbit}.",
        ],
        slips,
        lo=1,
    )


@generator(
    "r4a_orbit_stabiliser_count",
    level=19,
    presets={"easy": dict(tier="easy"), "medium": dict(tier="medium"), "hard": dict(tier="hard")},
)
@with_latex
def r4a_orbit_stabiliser_count(rng, tier="easy"):
    """Orbit and stabiliser sizes; the tiers are described in the module docstring."""
    if tier == "easy":
        return _easy(rng)
    if tier == "medium":
        return _medium(rng)
    check(tier == "hard", f"unknown tier {tier!r}")
    return _hard(rng)


# -- exam -------------------------------------------------------------------------------------------------------


@generator("exd_x_r4a_orbit_stabiliser_count", level=19, presets={"exam": dict(tier="exam")})
@with_latex
def exd_x_r4a_orbit_stabiliser_count(rng, tier="exam"):
    """Exam chain: stabiliser order, orbit size, fibre size of an action map and a stabiliser from an orbit size."""
    check(tier == "exam", f"unknown tier {tier!r}")
    for _ in attempts(3000, "two colourings with suitable stabilisers"):
        n = rng.choice([8, 9, 10, 12, 14, 15, 16, 18])
        black = _symmetric_black(rng, n)
        c = _colouring(n, black)
        stab, orbit, elements, images = _stab_and_orbit(n, c)
        if stab < 2 or orbit in (n, 2 * n) or not 3 <= len(black) <= n - 3:
            continue
        target = images[rng.choice([i for i in range(2 * n) if images[i] != c])]
        black2 = _symmetric_black(rng, n)
        z = _colouring(n, black2)
        stab_z, orbit_z, _e, _i = _stab_and_orbit(n, z)
        if (
            stab_z >= 2
            and orbit_z not in (n, 2 * n)
            and stab_z != stab
            and orbit_z != orbit
            and 3 <= len(black2) <= n - 3
        ):
            break
    sent = sum(1 for im in images if im == target)
    check(sent == stab, "the number of elements sending c to the target differs from |Stab(c)|")
    check(stab * orbit == 2 * n and stab_z * orbit_z == 2 * n, "|stabiliser| × |orbit| differs from |D_n|")
    return dict(
        text=(
            f"The vertices of a regular {n}-gon are labelled 0, 1, ..., {n - 1} in order. The dihedral group D_{n} of order "
            f"{2 * n} acts on black-and-white colourings of the vertices. The colouring c has exactly the vertices "
            f"{_black_text(c)} black."
        ),
        parts=[
            number_part(
                "How many elements of D_%d leave c unchanged?" % n,
                stab,
                3,
                [
                    f"Checking the {n} rotations and {n} reflections, exactly {stab} map the black set {_black_text(c)} to itself."
                ],
                [
                    (1, "stabiliser-order-trivial-assumed"),
                    (orbit, "stabiliser-order-as-orbit-size"),
                    (2 * n, "stabiliser-order-as-group-order"),
                    (n // 2 if n % 2 == 0 else None, None),
                ],
                sensible_range=(0, None),
            ),
            number_part(
                "How many different colourings can be obtained from c by elements of D_%d?" % n,
                orbit,
                2,
                [f"|orbit| = |D_{n}|/|stabiliser| = {2 * n}/{stab} = {orbit}."],
                [
                    (stab, "orbit-size-as-stabiliser-order"),
                    (2 * n, "orbit-size-whole-group"),
                    (n, "orbit-size-uses-n-not-2n"),
                    (2 * n - stab, None),
                ],
                follow_through=f"{2 * n}/part_a",
                sensible_range=(0, None),
            ),
            number_part(
                f"The colouring c' with black vertices {_black_text(target)} can be reached from c. How many elements of D_{n} send c to c'?",
                stab,
                2,
                [f"The elements sending c to c' form a coset of the stabiliser of c, so there are {stab} of them."],
                [
                    (1, "preimage-count-assumes-one-to-one"),
                    (orbit, "stabiliser-order-as-orbit-size"),
                    (2 * n, None),
                    (stab + 1, None),
                ],
                follow_through="part_a",
                sensible_range=(0, None),
            ),
            number_part(
                f"Another colouring c'' has {orbit_z} different colourings in its orbit under D_{n}. How many elements of D_{n} leave c'' unchanged?",
                stab_z,
                2,
                [f"|stabiliser| = |D_{n}|/|orbit| = {2 * n}/{orbit_z} = {stab_z}."],
                [
                    (orbit_z, "stabiliser-order-as-orbit-size"),
                    (n // orbit_z if n % orbit_z == 0 else None, "stabiliser-order-uses-n-not-2n"),
                    (2 * n, "stabiliser-order-as-group-order"),
                    (stab_z + 1, None),
                ],
                sensible_range=(0, None),
            ),
        ],
    )
